static void run_bu1000(void) {
    printf("bu1000 sizeof %zu alignof %zu\n", sizeof(bu1000), _Alignof(bu1000));
    for (unsigned i = 0; i < sizeof bu1000_op / sizeof bu1000_op[0]; i++) {
        bu1000 a, b, r = 0, s = 0;
        memcpy(&a, bu1000_v[bu1000_a[i]], sizeof a);
        memcpy(&b, bu1000_v[bu1000_b[i]], sizeof b);
        volatile unsigned k = bu1000_k[i];
        switch (bu1000_op[i]) {
        case 0: r = a + b; break;
        case 1: r = a - b; break;
        case 2: r = a * b; break;
        case 3: r = a / b; break;
        case 4: r = a % b; break;
        case 5: r = a & b; break;
        case 6: r = a | b; break;
        case 7: r = a ^ b; break;
        case 8: r = a << (bu1000)k; break;
        case 9: r = a >> (bu1000)k; break;
        case 10: r = a << k; break;
        case 11: r = a >> k; break;
        case 12: r = (a < b) | (a <= b) << 1 | (a > b) << 2 | (a >= b) << 3 | (a == b) << 4 | (a != b) << 5; break;
        case 13: r = a; r += b; break;
        case 14: r = a; r *= b; break;
        case 15: r = a; r >>= (bu1000)k; break;
        case 16: r = a ? b : a; s = a < b ? a : b; r ^= s; break;
        case 17: r = -a; break;
        case 18: r = ~a; break;
        case 19: r = !a; break;
        case 20: r = a; r++; break;
        case 21: r = a; --r; break;
        case 22: r = a; s = r++; r ^= s; break;
        }
        show(&r, 1000);
    }
}

